/// Method: PATCH /accounts/{account_id}/workers/observability/destinations/{slug}
#[actor(
    CloudflareUpdateDestinationsActor,
    inports::<100>(slug, configuration, enabled),
    outports::<50>(response, error),
    state(MemoryState)
)]
pub async fn cloudflare_update_destinations(
    context: ActorContext,
) -> Result<HashMap<String, Message>, Error> {
    let inputs = context.get_payload();
    let actor_config = context.get_config();

    let mut endpoint =
        "/accounts/{account_id}/workers/observability/destinations/{slug}".to_string();
    if let Some(val) = inputs.get("slug") {
        endpoint = endpoint.replace("{{slug}}", &super::message_to_str(val));
    }

    let url = format!("{}{}", BASE_URL.trim_end_matches('/'), endpoint);

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()?;

    let mut builder = client.patch(&url);
    builder = builder.header("Content-Type", "application/json");
    builder = apply_auth(actor_config, builder)?;

    let mut body = serde_json::Map::new();
    if let Some(val) = inputs.get("configuration") {
        body.insert("configuration".to_string(), val.clone().into());
    }
    if let Some(val) = inputs.get("enabled") {
        body.insert("enabled".to_string(), val.clone().into());
    }
    if !body.is_empty() {
        builder = builder.json(&serde_json::Value::Object(body));
    }

    let mut output = HashMap::new();
    match builder.send().await {
        Ok(resp) => {
            let status = resp.status().as_u16();
            let headers: HashMap<String, String> = resp
                .headers()
                .iter()
                .filter_map(|(k, v)| v.to_str().ok().map(|val| (k.to_string(), val.to_string())))
                .collect();
            let body_text = resp.text().await.unwrap_or_default();
            let body_value: Value =
                serde_json::from_str(&body_text).unwrap_or(Value::String(body_text));
            output.insert(
                "response".to_string(),
                Message::object(EncodableValue::from(json!({
                    "status": status,
                    "headers": headers,
                    "body": body_value,
                }))),
            );
        }
        Err(e) => {
            output.insert("error".to_string(), Message::Error(format!("PATCH /accounts/{{account_id}}/workers/observability/destinations/{{slug}} failed: {}", e).into()));
        }
    }

    Ok(output)
}

